// Home Lab alert banner: CPU/memory pressure on the Proxmox host.
// Split metrics attaches mem + uptime to its CPU (out0) message, so a
// single feed evaluates the whole tab state.
var cpu = (typeof msg.payload === 'number') ? msg.payload : -1;
var mem = (typeof msg.mem === 'number') ? msg.mem : 0;
var up = msg.uptime || '';
var sev = 'ok';
var parts = [];
if (cpu < 0) {
  sev = 'critical';
  parts.push('Proxmox data unavailable');
} else {
  if (cpu >= 90) { sev = 'critical'; parts.push('CPU ' + cpu + '%'); }
  else if (cpu >= 75) {
    sev = 'warning'; parts.push('CPU ' + cpu + '%');
  }
  if (mem >= 90) { sev = 'critical'; parts.push('Memory ' + mem + '%'); }
  else if (mem >= 75) {
    if (sev === 'ok') { sev = 'warning'; }
    parts.push('Memory ' + mem + '%');
  }
  if (sev === 'ok') { parts.push('Proxmox OK' + (up ? ' - up ' + up : '')); }
}
node.status({fill: sev === 'ok' ? 'green' : (sev === 'critical' ? 'red' : 'yellow'), shape: 'dot', text: sev});
msg.payload = {severity: sev, message: parts.join(' | ')};
return msg;

// Credentials come from env vars -- never hardcoded.
var base = env.get('PROXMOX_URL');
var tok  = env.get('PROXMOX_TOKEN');
if (!base || !tok) {
  node.status({fill:'red',shape:'ring',text:'missing config'});
  return null;
}
var node = env.get('PROXMOX_NODE') || 'pve';
msg.method = 'GET';
msg.url = base.replace(/\/+$/, '') + '/api2/json/nodes/' + node + '/status';
msg.headers = {};
msg.headers['Authorization'] = 'PVEAPIToken=' + tok;
msg.rejectUnauthorized = false;
return msg;

var d = (msg.payload && msg.payload.data) ? msg.payload.data : null;
if (!d) {
  node.status({fill:'red',shape:'ring',text:'no data'});
  // out0 feeds the alert evaluator: payload -1 is its 'data
  // unavailable' marker -> a CRITICAL banner instead of a blank one.
  // The gauge clamps -1 to its 0 floor (cosmetic; the banner is the
  // authoritative alert element).
  return [{payload: -1, mem: -1, uptime: ''}, null, null, null, null, null, null, null];
}
var cpu = Math.round((d.cpu || 0) * 1000) / 10;
var memUsed = (d.memory && d.memory.used) || 0;
var memTot = (d.memory && d.memory.total) || 1;
var mem = Math.round(memUsed / memTot * 1000) / 10;
var up = d.uptime || 0;
var days = Math.floor(up / 86400), hrs = Math.floor((up % 86400) / 3600);
node.status({fill:'green',shape:'dot',text:cpu + '% cpu'});
// Human-readable byte formatting for the disk/swap/memory rows.
function gb(v) { return (Math.round(v / 1073741824 * 10) / 10) + ' GB'; }
function pct(u, t) { return t ? Math.round(u / t * 1000) / 10 + '%' : 'n/a'; }
// Nested sub-objects are flattened onto the payload so the Host Detail
// template can reach them with plain dotted paths -- confirmed present in
// the live response by tools/probe_proxmox_status.py.
var rootfs = d.rootfs || {}, swap = d.swap || {};
var mem2 = d.memory || {};
var ci = d.cpuinfo || {}, kd = d['current-kernel'] || {}, la = d.loadavg || [];
var detail = {
  payload: {
    pveversion: d.pveversion || 'unknown',
    kversion: d.kversion || kd.release || 'unknown',
    model: ci.model || 'unknown',
    cores: ci.cores || ci.cpus || '?',
    mhz: ci.mhz || '?',
    load1: (la[0] != null ? Math.round(la[0] * 100) / 100 : '?'),
    load5: (la[1] != null ? Math.round(la[1] * 100) / 100 : '?'),
    load15: (la[2] != null ? Math.round(la[2] * 100) / 100 : '?'),
    uptime: days + 'd ' + hrs + 'h'
  }
};
var mSwap = {payload: pct(swap.used, swap.total) + ' of ' + gb(swap.total || 0)};
var mDisk = {payload: pct(rootfs.used, rootfs.total) + ' of ' + gb(rootfs.total || 0)
  + '  (' + gb(rootfs.avail || 0) + ' free)'};
var mMem  = {payload: gb(mem2.used || 0) + ' of ' + gb(mem2.total || 0)
  + '  (' + gb(mem2.available || 0) + ' avail)'};
var mCpu = {payload: cpu, mem: mem, uptime: days + 'd ' + hrs + 'h'};
var mMemG = {payload: mem};
var mStat = {payload: 'Up ' + days + 'd ' + hrs + 'h' + (d.loadavg ? ' | load ' + (Math.round(d.loadavg[0]*100)/100) : '')};
var mChart = {payload: cpu, topic: 'cpu'};
return [mCpu, mMemG, mStat, mChart, detail, mSwap, mDisk, mMem];

// Devices alert banner. Two feeds arrive here:
//  - control results ('OK (200)', 'ERROR ...', 'Set HUBITAT_...' when
//    config is missing) from Format result / Build Maker API call;
//  - the 300s list poll from Format device list: a device COUNT
//    (number) on success, 'ERROR ...' when the hub is unreachable.
var p = String(msg.payload || '');
var sev = 'ok';
var text;
if (typeof msg.payload === 'number') {
  // list poll succeeded: N devices reachable = hub is up
  text = msg.payload + ' devices reachable';
} else if (p.indexOf('ERROR') === 0) {
  sev = 'critical';
  text = p.slice(0, 120);
} else if (p.indexOf('Set HUBITAT') === 0) {
  sev = 'warning';
  text = 'Hubitat config missing: set HUBITAT_APP_ID / ACCESS_TOKEN / DEVICE_ID';
} else if (p.indexOf('OK') === 0) {
  text = 'Hubitat control OK';
} else {
  sev = 'info';
  text = p || 'Awaiting first result';
}
node.status({fill: sev === 'ok' ? 'green' : (sev === 'critical' ? 'red' : 'yellow'), shape: 'dot', text: sev});
msg.payload = {severity: sev, message: text};
return msg;

var base = env.get('HUBITAT_URL') || '';
var app  = env.get('HUBITAT_APP_ID') || '';
var tok  = env.get('HUBITAT_ACCESS_TOKEN') || env.get('HUBITAT_API_KEY') || '';
if (!base || !app || !tok) {
  node.status({fill:'red',shape:'ring',text:'missing config'});
  msg.payload = [];
  return [null, msg];
}
msg.method = 'GET';
msg.url = base.replace(/\/+$/, '') + '/apps/api/' + app + '/devices?access_token=' + tok;
node.status({fill:'blue',shape:'dot',text:'listing'});
return [msg, null];

var body = msg.payload;
if (msg.error || !msg.statusCode) {
  node.status({fill:'red',shape:'ring',text:'unreachable'});
  msg.payload = [];
  // out1 feeds Device Count AND the alert evaluator: an explicit
  // ERROR string makes the banner critical ('hub unreachable'),
  // which a count of 0 cannot distinguish from 'no devices'.
  var e = {payload: 'ERROR: Hubitat unreachable (' + (msg.error || 'no response') + ')'};
  return [msg, e];
}
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = []; }
}
var list = Array.isArray(body) ? body : (body && body.devices) || [];
node.status({fill:'green',shape:'dot',text:list.length + ' devices'});
msg.payload = list;
var c = {payload: list.length};
return [msg, c];

// Hubitat Maker API: GET /apps/api/<appId>/devices/<devId>/<cmd>/<value>?access_token=<tok>
var base = env.get('HUBITAT_URL') || 'http://hubitat.local';
var app  = env.get('HUBITAT_APP_ID') || '';
var tok  = env.get('HUBITAT_ACCESS_TOKEN') || env.get('HUBITAT_API_KEY') || '';
var dev  = env.get('HUBITAT_DEVICE_ID') || '';
if (!app || !tok || !dev) {
  node.status({fill:'red',shape:'ring',text:'missing config'});
  msg.payload = 'Set HUBITAT_APP_ID, HUBITAT_ACCESS_TOKEN and HUBITAT_DEVICE_ID in the LXC env';
  return [null, msg];
}
var cmd, val = null;
if (msg.topic === 'hubitat/power') { cmd = msg.payload ? 'on' : 'off'; }
else if (msg.topic === 'hubitat/level') { cmd = 'setLevel'; val = msg.payload; }
else { node.status({fill:'grey',shape:'ring',text:'ignored'}); return null; }
var url = base.replace(/\/+$/, '') + '/apps/api/' + app + '/devices/' + dev + '/' + cmd;
if (val !== null) { url += '/' + val; }
url += '?access_token=' + tok;
msg.method = 'GET';
msg.url = url;
node.status({fill:'blue',shape:'dot',text:cmd});
return [msg, null];

// http request sets msg.error on a transport failure.
if (msg.error || !msg.statusCode) {
  node.status({fill:'red',shape:'ring',text:'unreachable'});
  msg.payload = 'ERROR: Hubitat unreachable (' + (msg.error || msg.payload || 'no response') + ')';
  return [msg, msg];
}
if (msg.statusCode >= 200 && msg.statusCode < 300) {
  node.status({fill:'green',shape:'dot',text:'ok'});
  msg.payload = 'OK (' + msg.statusCode + ')';
} else {
  node.status({fill:'red',shape:'ring',text:'http ' + msg.statusCode});
  var body = (typeof msg.payload === 'string') ? msg.payload : JSON.stringify(msg.payload);
  msg.payload = 'ERROR HTTP ' + msg.statusCode + ': ' + String(body).slice(0, 200);
}
return [msg, msg];

// Home Assistant WebSocket client.
// STATE PATH  : connect once, authenticate, pull all states, then re-emit
//               state_changed events as {entityId, domain, state, friendlyName, isOn}.
// CONTROL PATH: a boolean from the dashboard switch, or an explicit
//               {domain, service, entityId} on topic 'ha/control', becomes a
//               REST service call.
var WS_PATH = '/api/websocket';
var READ_ONLY = ['sensor', 'binary_sensor', 'input_datetime', 'weather', 'zone', 'device_tracker'];

function normalise(eid, st) {
  var a = st.attributes || {};
  return {
    entityId: eid,
    domain: eid.split('.')[0],
    state: st.state,
    friendlyName: a.friendly_name || eid,
    isOn: st.state === 'on',
    brightnessPct: (a.brightness_pct === undefined ? null : a.brightness_pct)
  };
}

function startWS() {
  var baseUrl = env.get('HA_URL') || 'http://homeassistant.local:8123';
  var token = env.get('HA_TOKEN');
  if (!token) { node.status({fill:'red', shape:'ring', text:'no HA_TOKEN'}); return; }
  var wsUrl = baseUrl.replace(/^http/, 'ws').replace(/\/+$/, '') + WS_PATH;
  var states = {};
  var s = new ws(wsUrl);
  context.set('ha_socket', s);
  node.status({fill:'yellow', shape:'ring', text:'connecting'});
  s.on('open', function () {
    s.send(JSON.stringify({type: 'auth', access_token: token}));
  });
  s.on('message', function (data) {
    var m;
    try { m = JSON.parse(data); } catch (e) { return; }
    if (m.type === 'auth_required') {
      s.send(JSON.stringify({type: 'auth', access_token: token}));
    } else if (m.type === 'auth_ok') {
      node.status({fill:'green', shape:'dot', text:'connected'});
      s.send(JSON.stringify({type: 'get_states'}));
      s.send(JSON.stringify({type: 'subscribe_events', event_type: 'state_changed'}));
    } else if (m.type === 'auth_invalid') {
      node.status({fill:'red', shape:'ring', text:'auth failed'});
      context.set('ha_socket', null);
      try { s.close(); } catch (e) {}
    } else if (m.type === 'result' && m.success && Array.isArray(m.result)) {
      var n = 0;
      m.result.forEach(function (x) { if (x.entity_id) { states[x.entity_id] = x; n++; } });
      node.status({fill:'green', shape:'dot', text:n + ' entities'});
      node.send([null, {payload: n, topic: 'ha/state_count'}]);
    } else if (m.type === 'event' && m.event && m.event.data) {
      var eid = m.event.data.entity_id;
      var ns = m.event.data.new_state;
      if (eid && ns) {
        states[eid] = ns;
        node.send([null, {payload: normalise(eid, ns), topic: 'ha/entity/' + eid + '/state'}]);
      }
    }
  });
  s.on('close', function () { context.set('ha_socket', null); node.status({fill:'grey', shape:'ring', text:'closed'}); });
  s.on('error', function () { node.status({fill:'red', shape:'ring', text:'WS error'}); });
}

// --- per message ------------------------------------------------------------
// Any input -- including the 60s Sync States tick -- makes sure we are connected.
if (!context.get('ha_socket')) { startWS(); }

var req = null;
if (msg.topic === 'ha/control' && msg.payload && typeof msg.payload === 'object') {
  req = msg.payload;                                    // explicit request
} else if (typeof msg.payload === 'boolean') {         // dashboard ui_switch
  // CAVEAT: ui_switch may emit its initial value when the page loads, which
  // actuates once. Harmless for an already-off light; revisit if it matters.
  req = { entityId: env.get('HA_ENTITY_ID'), domain: 'light',
          service: msg.payload ? 'turn_on' : 'turn_off' };
}
if (!req) { return null; }                             // tick only: connect, never actuate
if (!req.entityId) { node.status({fill:'red', shape:'ring', text:'no HA_ENTITY_ID'}); return null; }
if (!req.service)  { node.status({fill:'red', shape:'ring', text:'no service'}); return null; }
if (READ_ONLY.indexOf(req.domain) >= 0) {
  node.status({fill:'red', shape:'ring', text:'read-only'}); return null;
}
var base = (env.get('HA_URL') || '').replace(/\/+$/, '');
if (!base) { node.status({fill:'red', shape:'ring', text:'no HA_URL'}); return null; }
var body = {entity_id: req.entityId};
if (req.serviceData) { for (var k in req.serviceData) { body[k] = req.serviceData[k]; } }
node.status({fill:'blue', shape:'dot', text:req.service});
return [{payload: {url: base + '/api/services/' + req.domain + '/' + req.service,
                   method: 'POST', body: body},
         topic: 'ha/control'}, null];

// Format a Home Assistant service call for the HTTP request node.
// Classic function node: the body runs per message and returns what to emit.
// Guard the url so a stray state message cannot throw on msg.url.replace().
if (!msg.url) { node.status({fill:'grey', shape:'ring', text:'no url'}); return null; }
msg.headers = {
  'Authorization': 'Bearer ' + (env.get('HA_TOKEN') || ''),
  'Content-Type': 'application/json'
};
msg.method = msg.method || 'POST';
msg.url = String(msg.url).replace(/\/+$/, '');
msg.payload = msg.body || {};
msg.rejectUnauthorized = false;
node.status({fill:'green', shape:'dot', text:'sending to HA'});
return msg;

// Network alert banner: controller reachability + client-count anomaly.
// Split client data tags its count output with topic 'unifi/error' when
// the poll failed, so 'no clients' (warning) is distinguishable from an
// unreachable controller (critical).
var n = (typeof msg.payload === 'number') ? msg.payload : -1;
var sev = 'ok';
var text;
if (n < 0 || msg.topic === 'unifi/error') {
  sev = 'critical';
  text = 'UniFi controller unreachable' + (msg._error ? ' -- ' + String(msg._error).slice(0, 100) : '');
} else if (n === 0) {
  sev = 'warning';
  text = 'No clients online';
} else {
  text = n + ' clients online';
}
node.status({fill: sev === 'ok' ? 'green' : (sev === 'critical' ? 'red' : 'yellow'), shape: 'dot', text: sev});
msg.payload = {severity: sev, message: text};
return msg;

// UniFi controllers need auth. Credentials come from env vars.
// UNIFI_URL may carry a path prefix: UniFi OS (UDM/Cloud Gateway) serves
// the Network app under /proxy/network, self-hosted controllers do not.
var base = env.get('UNIFI_URL');
var site = env.get('UNIFI_SITE') || 'default';
var key  = env.get('UNIFI_API_KEY');
var user = env.get('UNIFI_USERNAME');
var pass = env.get('UNIFI_PASSWORD');
msg.rejectUnauthorized = false;
msg.headers = {'Accept': 'application/json'};
if (!base) {
  node.status({fill:'red',shape:'ring',text:'no UNIFI_URL'});
  return [null, null, {payload: [], topic: 'unifi/error', _error: 'UNIFI_URL is not set. Use https://<host>/proxy/network for a UniFi OS console, or https://<host>:8443 for a self-hosted controller'}];
}
base = base.replace(/\/+$/, '');
msg.url_stat = base + '/api/s/' + site + '/stat/sta';
if (key) {
  node.status({fill:'green',shape:'dot',text:'api key'});
  msg.method = 'GET';
  msg.url = msg.url_stat;
  msg.headers['X-API-KEY'] = key;
  // out1 is the API-key path and MUST still go through the HTTP request
  // node. Returning it on out0 (the login path) sent it straight to the
  // parser, which then read the inject's Date payload instead of client
  // data and always rendered 0 clients. Both auth routes converge on the
  // same HTTP node; out0 only differs in that it needs a login first.
  return [null, msg, null];
}
if (!user || !pass) {
  node.status({fill:'red',shape:'ring',text:'no credentials'});
  return [null, null, {payload: [], topic: 'unifi/error', _error: 'Set UNIFI_API_KEY, or UNIFI_USERNAME + UNIFI_PASSWORD, in the service environment'}];
}
// Pick the login endpoint. A UniFi OS console (base carries
// /proxy/network) authenticates at the console root via /api/auth/login;
// self-hosted controllers use /api/login. UNIFI_LOGIN_URL overrides both.
var login = env.get('UNIFI_LOGIN_URL');
if (!login) {
  login = base + '/api/login';
  var m = base.match(/^(https?:\/\/[^\/]+)\/proxy\/network/);
  if (m) { login = m[1] + '/api/auth/login'; }
}
node.status({fill:'blue',shape:'dot',text:'logging in'});
msg.method = 'POST';
msg.url = login;
msg.headers['Content-Type'] = 'application/json';
msg.payload = JSON.stringify({username: user, password: pass, remember: true});
return [msg, null];

// Carry the UniFi session cookie (or X-CSRF-Token on newer builds)
// into the stat request.
var h = msg.headers || {};
var setCookie = h['set-cookie'] || h['Set-Cookie'];
var cookie = null;
if (Array.isArray(setCookie)) { setCookie = setCookie.join('; '); }
if (setCookie) {
  var part = String(setCookie).split(';')[0];
  if (part) { cookie = part; }
}
if (!cookie) {
  node.status({fill:'red',shape:'ring',text:'login failed'});
  msg.payload = [];
  msg.topic = 'unifi/error';
  msg._error = 'UniFi login returned no session cookie (HTTP ' + (msg.statusCode || '?') + ')';
  // Failed login -> the PARSER's error branch, not another stat
  // request with the login URL (bogus request, drops the real
  // error). The parser tags the count 'unifi/error' so the alert
  // banner reports the controller as unreachable (critical).
  return [msg, msg];
}
node.status({fill:'green',shape:'dot',text:'session ok'});
msg.method = 'GET';
msg.url = msg.url_stat;
msg.headers = {'Accept': 'application/json'};
if (msg.csrfToken || (h['x-csrf-token'])) {
  msg.headers['X-CSRF-Token'] = msg.csrfToken || h['x-csrf-token'];
}
msg.headers['Cookie'] = cookie;
return msg;

// Handles both the success path and the config-error path.
if (msg.topic === 'unifi/error' || msg._error) {
  node.status({fill:'red',shape:'ring',text:'error'});
  var errMsg = msg._error || String(msg.payload || '');
  // out0 feeds Clients Online + the alert evaluator. Keep the
  // error topic on the count so the banner says 'controller
  // unreachable' (critical), not 'no clients' (warning).
  return [ {payload: 0, topic: 'unifi/error', _error: errMsg},
           {payload: 'ERROR: ' + errMsg} ];
}
var data = (msg.payload && msg.payload.data) ? msg.payload.data : [];
var rows = [];
data.forEach(function (c) {
  rows.push({hostname: c.hostname || c.name || c.mac, ip: (c.ip || (c['ip'] || '')), mac: c.mac || ''});
});
node.status({fill:'green',shape:'dot',text:rows.length + ' clients'});
return [ {payload: rows.length}, {payload: rows} ];

var task = (typeof msg.payload === 'string' ? msg.payload : '').trim();
if (!task) { node.status({fill:'grey',shape:'ring',text:'empty'}); return null; }
var cards = flow.get('kanban_cards') || [];
cards.push({task: task, status: 'todo'});
flow.set('kanban_cards', cards);
node.status({fill:'green',shape:'dot',text:cards.length + ' cards'});
msg.payload = cards;
return [msg, msg];

var cards = flow.get('kanban_cards') || [];
node.status({fill:'blue',shape:'dot',text:cards.length + ' cards'});
msg.payload = cards;
return [msg, msg];

// System Health alert banner: Prometheus targets/probes + node pressure.
// Parse health summary attaches the full stat map to its first output,
// so one message evaluates the whole stack.
var m = msg.stats || {};
var cpu = m.pve_cpu, mem = m.pve_mem;
var tUp = m.targets_up, tTot = m.targets_total;
var pOk = m.probes_ok, pTot = m.probes_total;
function pct(v) { return Math.round(v * 10) / 10 + '%'; }
function escalate(s) {
  if (s === 'critical') { sev = 'critical'; }
  else if (s === 'warning' && sev !== 'critical') { sev = 'warning'; }
}
var sev = 'ok';
var parts = [];
if (!m || msg.payload === -1) {
  // Parse health summary marks total failure with payload:-1 (stats
  // null) or payload:-1 + empty stats (Prometheus up, nothing scraped).
  sev = 'critical';
  parts.push('Monitoring data unavailable');
} else {
if (typeof cpu === 'number') {
  if (cpu >= 90) { escalate('critical'); parts.push('CPU ' + pct(cpu)); }
  else if (cpu >= 75) { escalate('warning'); parts.push('CPU ' + pct(cpu)); }
}
if (typeof mem === 'number') {
  if (mem >= 90) { escalate('critical'); parts.push('Memory ' + pct(mem)); }
  else if (mem >= 75) { escalate('warning'); parts.push('Memory ' + pct(mem)); }
}
if (tTot > 0 && tUp < tTot) {
  escalate(tUp === 0 ? 'critical' : 'warning');
  parts.push('Targets ' + tUp + '/' + tTot);
}
if (pTot > 0 && pOk < pTot) {
  escalate(pOk === 0 ? 'critical' : 'warning');
  parts.push('Probes ' + pOk + '/' + pTot);
}
if (sev === 'ok') { parts.push('All monitored systems healthy'); }
}
node.status({fill: sev === 'ok' ? 'green' : (sev === 'critical' ? 'red' : 'yellow'), shape: 'dot', text: sev});
msg.payload = {severity: sev, message: parts.join(' | ')};
return msg;

// One instant query returns every summary stat, tagged with a `stat`
// label so a single HTTP round trip feeds all five widgets. Every
// expression was verified live against the co-located stack.
var base = (env.get('PROMETHEUS_URL') || 'http://192.168.4.145:9090').replace(/\/+$/, '');
var q = 'label_replace(count(up == 1), "stat", "targets_up", "", "")'
  + ' or label_replace(count(up), "stat", "targets_total", "", "")'
  + ' or label_replace(100 - (avg(rate(node_cpu_seconds_total{mode="idle"}[5m])) * 100), "stat", "pve_cpu", "", "")'
  + ' or label_replace(100 * (1 - (node_memory_MemAvailable_bytes / node_memory_MemTotal_bytes)), "stat", "pve_mem", "", "")'
  + ' or label_replace(count(probe_success == 1), "stat", "probes_ok", "", "")'
  + ' or label_replace(count(probe_success), "stat", "probes_total", "", "")'
  + ' or label_replace((time() - node_boot_time_seconds) / 86400, "stat", "pve_uptime_days", "", "")';
msg.method = 'GET';
msg.url = base + '/api/v1/query?query=' + encodeURIComponent(q);
return msg;

// Map the stat-labelled instant query onto one message per widget.
// Missing stats degrade to 0 rather than 'undefined' text.
var r = msg.payload;
if (!r || r.status !== 'success' || !r.data || !Array.isArray(r.data.result)) {
  node.status({fill:'red',shape:'ring',text:'no data'});
  // out0 feeds the alert evaluator. An empty stat map would read as
  // 'everything healthy' there -- send stats: null so the banner
  // reports 'monitoring unavailable' (critical) instead of lying.
  var mFail = { payload: -1, stats: null };
  return [mFail, null, null, null, null];
}
var m = {};
r.data.result.forEach(function (s) {
  if (s.metric && s.metric.stat && s.value) { m[s.metric.stat] = parseFloat(s.value[1]); }
});
// Prometheus reachable but zero stats scraped: same as down for
// alerting purposes -- the banner must not read it as 'healthy'.
